
--[dbo].[SP_InsertStockTransactions] '<StockTransactionHeader xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema"><CreatedUserID>4423</CreatedUserID><LastModUserID>4423</LastModUserID><CreatedDate>2022-02-26T07:40:15.161Z</CreatedDate><LastModDate>2022-02-26T07:40:15.161Z</LastModDate><Id>0</Id><IsPrint>false</IsPrint><IsApproved>false</IsApproved><TransactionType>GR</TransactionType><TransactionDate>2022-02-26T07:40:15.161Z</TransactionDate><PropertyID>10</PropertyID><LocationID>46</LocationID><ReferenceNo>C21-2197</ReferenceNo><SupplierID>644</SupplierID><ReferenceID>3814</ReferenceID><DepartmentID>0</DepartmentID><UserProfileID>4423</UserProfileID><TransferLocationID>0</TransferLocationID><TransactionID>3</TransactionID><Mode>R</Mode><SuppCurrencyID>86</SuppCurrencyID><ExchangeRate>0</ExchangeRate><InvoiceDate>2022-02-17T00:00:00</InvoiceDate><IsTrasferIn>false</IsTrasferIn><StockDetailList><StockTransactionDetail><IPAddress /><CreatedUserID>4423</CreatedUserID><LastModUserID>4423</LastModUserID><CreatedDate>2022-02-26T07:40:15.161Z</CreatedDate><LastModDate>2022-02-26T07:40:15.161Z</LastModDate><Id>0</Id><StockTransactionHeaderID>-1</StockTransactionHeaderID><StockItemID>52862</StockItemID><Quantity>1</Quantity><UnitPrice>2704.8</UnitPrice><TxnUnitID>426</TxnUnitID><MasterUnitID>0</MasterUnitID><MasterUnitConversion>0</MasterUnitConversion><ReportUnitID>0</ReportUnitID><ReportUnitConversion>0</ReportUnitConversion><DiscountValue>0</DiscountValue><DiscountPercentage>0</DiscountPercentage><TimeStamp>0</TimeStamp><StockMasterQuantity>0</StockMasterQuantity><StockMasterAveragePrice>0</StockMasterAveragePrice><NewQuantity>1</NewQuantity><NewAveragePrice>0</NewAveragePrice><Remarks /><UserProfileId>4423</UserProfileId><CostTransactionAccountID>0</CostTransactionAccountID><PurchaseTransactionAccountID>0</PurchaseTransactionAccountID><TxnType>P</TxnType><BalanceQuantity>1</BalanceQuantity><ReturnQuantity>0</ReturnQuantity>