portUnitID><ReportUnitConversion>0</ReportUnitConversion><DiscountValue>0</DiscountValue><DiscountPercentage>0</DiscountPercentage><TimeStamp>0</TimeStamp><StockMasterQuantity>0</StockMasterQuantity><StockMasterAveragePrice>0</StockMasterAveragePrice><NewQuantity>1</NewQuantity><NewAveragePrice>0</NewAveragePrice><Remarks /><UserProfileId>4423</UserProfileId><CostTransactionAccountID>0</CostTransactionAccountID><PurchaseTransactionAccountID>0</PurchaseTransactionAccountID><TxnType>P</TxnType><BalanceQuantity>1</BalanceQuantity><ReturnQuantity>0</ReturnQuantity><ItemUnitPriceInSuppCurrency>0</ItemUnitPriceInSuppCurrency><TBPHeaderId>0</TBPHeaderId><CurrencyId>86</CurrencyId><BrandedItem xsi:nil="true" /><AccName>Engineering Stock                                 </AccName></StockTransactionDetail><StockTransactionDetail><IPAddress /><CreatedUserID>4423</CreatedUserID><LastModUserID>4423</LastModUserID><CreatedDate>2022-02-26T07:40:15.161Z</CreatedDate><LastModDate>2022-02-26T07:40:15.161Z</LastModDate><Id>0</Id><StockTransactionHeaderID>-1</StockTransactionHeaderID><StockItemID>56018</StockItemID><Quantity>1</Quantity><UnitPrice>1021.5</UnitPrice><TxnUnitID>578</TxnUnitID><MasterUnitID>0</MasterUnitID><MasterUnitConversion>0</MasterUnitConversion><ReportUnitID>0</ReportUnitID><ReportUnitConversion>0</ReportUnitConversion><DiscountValue>0</DiscountValue><DiscountPercentage>0</DiscountPercentage><TimeStamp>0</TimeStamp><StockMasterQuantity>0</StockMasterQuantity><StockMasterAveragePrice>0</StockMasterAveragePrice><NewQuantity>1</NewQuantity><NewAveragePrice>0</NewAveragePrice><Remarks /><UserProfileId>4423</UserProfileId><CostTransactionAccountID>0</CostTransactionAccountID><PurchaseTransactionAccountID>0</PurchaseTransactionAccountID><TxnType>P</TxnType><BalanceQuantity>1</BalanceQuantity><ReturnQuantity>0</ReturnQuantity><ItemUnitPriceInSuppCurrency>0</ItemUnitPriceInSuppCurrency><TBPHeaderId>0</TBPHeaderId><CurrencyId>86</CurrencyId><BrandedItem xsi:nil="true" /><Acc